// === Tab: mySketch ===
let cellCount = 10

let cellSize;
let shapes = [];
let clr = '#ffffff';
let ctx

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	ctx = drawingContext;
	cellSize = width / cellCount;
	for (let i = 0; i < cellCount; i++) {
		shapes[i] = [];
		for (let j = 0; j < cellCount; j++) {
			let x = i * cellSize + cellSize / 2;
			let y = j * cellSize + cellSize / 2;
			let type = random([0, 1]);
			shapes[i][j] = { x: x, y: y, w: cellSize, t: type };
		}
	}

	background(0);
	noFill();
	strokeWeight(width * 0.001);
	stroke(clr);
	ctx.shadowBlur = width * 0.02;
	ctx.shadowColor = '#00ffaa';
	for (let i = 0; i < cellCount; i++) {
		for (let j = 0; j < cellCount; j++) {
			let s = shapes[i][j];
			let top = j > 0 ? shapes[i][j - 1].t : null;
			let bottom = j < cellCount - 1 ? shapes[i][j + 1].t : null;
			let left = i > 0 ? shapes[i - 1][j].t : null;
			let right = i < cellCount - 1 ? shapes[i + 1][j].t : null;
			let angle = 0;
			let matches = [top, bottom, left, right].filter(v => v == s.t).length;
			if (matches == 1) {
				if (s.t == bottom) {
					angle = PI * 0.5;
				} else if (s.t == left) {
					angle = PI;
				} else if (s.t == top) {
					angle = PI * 1.5;
				}
				connect1(s.x, s.y, s.w, angle);
			} else if (matches == 2) {
				if (top != bottom && right != left) {
					if (bottom == s.t && left == s.t) angle = PI * 0.5
					else if (left == s.t && top == s.t) angle = PI
					else if (top == s.t && right == s.t) angle = PI * 1.5
					connect1to2(s.x, s.y, s.w, angle);
				} else {
					if (s.t == bottom) angle = PI * 0.5;
					connect1to3(s.x, s.y, s.w, angle);
				}
			} else if (matches == 3) {
				if (s.t != right) angle = PI * 0.5;
				else if (s.t != bottom) angle = PI;
				else if (s.t != left) angle = PI * 1.5;
				connect3(s.x, s.y, s.w, angle);
			} else if (matches == 4) {
				connect4(s.x, s.y, s.w);
			} else {
			}
		}
	}

}

