function connect1(x, y, w, a) {
	let type = int(random(2));
	push();
	translate(x, y);
	rotate(a);
	scale(1, random([-1, 1]));
	if (type == 0) {
		line(0, 0, w / 2, 0);
		beginShape();
		vertex(w / 2, -w / 4);
		vertex(w / 8 * 3, -w / 4);
		vertex(w / 8, -w / 2);
		vertex(0, -w / 2);
		vertex(-w / 8, -w / 8 * 3);
		vertex(-w / 4, -w / 8 * 3);
		endShape();
		beginShape();
		vertex(w / 2, w / 4);
		vertex(-w / 8, w / 4);
		vertex(-w / 4, w / 8);
		vertex(-w / 8 * 3, w / 8);
		endShape();
		noStroke();
		fill(clr);
		circle(0, 0, w * 0.09);
		circle(-w / 4, -w / 8 * 3, w * 0.09);
		circle(-w / 8 * 3, w / 8, w * 0.09);
	} else if (type == 1) {
		line(w / 2, -w / 4, -w / 8 * 3, -w / 4);
		line(-w / 4, -w / 8, w / 4, -w / 8);
		line(w / 4, -w / 8, w / 8 * 3, 0);
		line(-w / 8, 0, w / 2, 0);
		line(-w / 4, w / 4, w / 2, w / 4);
		line(-w / 4, w / 4, -w / 4, w / 8 * 3);
		fill(clr);
		noStroke();
		circle(-w / 8 * 3, -w / 4, w * 0.09);
		circle(-w / 4, w / 8 * 3, w * 0.09);
		circle(-w / 8, 0, w * 0.09);
		circle(-w / 4, -w / 8, w * 0.09);
	}
	pop();


}

function connect1to2(x, y, w, a) {
	let type = int(random(2));
	push();
	translate(x, y);
	rotate(a);
	if (type == 0) {
		line(w / 4, w / 2, w / 4, w / 4);
		line(w / 4, w / 4, w / 2, w / 4);
		line(0, w / 8 * 3, -w / 8, w / 4);
		line(-w / 8, w / 4, -w / 8, -w / 4);
		line(-w / 4, w / 2, -w / 4, -w / 8 * 3);
		line(w / 2, -w / 4, w / 4, -w / 4);
		beginShape();
		vertex(0, w / 2);
		vertex(0, w / 8);
		vertex(w / 8, 0);
		vertex(w / 2, 0);
		endShape();
		fill(clr);
		noStroke();
		circle(-w / 8, -w / 4, w * 0.09);
		circle(-w / 4, -w / 8 * 3, w * 0.09);
		circle(w / 4, -w / 4, w * 0.09);
	} else if (type == 1) {
		line(-w / 4, w / 2, -w / 4, -w / 8 * 3);
		line(-w / 4, w / 2, -w / 8, w / 8 * 3);
		line(-w / 8, 0, -w / 8, w / 8 * 3);
		line(0, w / 2, 0, -w / 4);
		line(w / 2, -w / 4, 0, -w / 4);
		line(w / 4, w / 2, w / 4, w / 4);
		line(w / 4, w / 4, w / 2, w / 4);
		line(w / 2, 0, w / 8 * 3, 0);
		line(w / 8, -w / 4, w / 8 * 3, 0);
		line(w / 4, w / 8 * 3, w / 8, w / 4);
		line(w / 8, w / 4, w / 8, w / 8);
		fill(clr);
		noStroke();
		circle(-w / 4, -w / 8 * 3, w * 0.09);
		circle(-w / 8, 0, w * 0.09);
		circle(w / 8, w / 8, w * 0.09);
	}
	pop();
}

function connect1to3(x, y, w, a) {
	let type = int(random(2));
	push();
	translate(x, y);
	rotate(a);
	scale(random([-1, 1]), 1);
	if (type == 0) {
		line(w / 2, -w / 4, -w / 2, -w / 4);
		line(w / 2, 0, -w / 2, 0);
		line(-w / 8 * 3, 0, -w / 4, -w / 8);
		line(w / 8 * 3, -w / 8, -w / 4, -w / 8);
		line(w / 2, w / 4, -w / 2, w / 4);
		line(w / 8, w / 8, -w / 8, w / 8);
		line(-w / 4, w / 4, -w / 8, w / 8);
		noStroke();
		fill(clr);
		circle(w / 8 * 3, -w / 8, w * 0.09);
		circle(w / 8, w / 8, w * 0.09);
	} else if (type == 1) {
		beginShape();
		vertex(-w / 2, -w / 4);
		vertex(-w / 8, -w / 4);
		vertex(w / 8 * 3, w / 4);
		endShape();
		beginShape();
		vertex(-w / 2, 0);
		vertex(-w / 8, 0);
		vertex(w / 8, w / 4);
		endShape();
		line(-w / 2, w / 4, w / 2, w / 4);
		line(-w / 8 * 3, w / 8 * 3, -w / 8, w / 8 * 3);
		line(-w / 8, w / 4, -w / 8, w / 8 * 3);
		beginShape();
		vertex(w / 2, 0);
		vertex(w / 4, 0);
		vertex(w / 4, -w / 4);
		vertex(w / 2, -w / 4);
		endShape();
		noStroke();
		fill(clr);
		circle(-w / 8 * 3, w / 8 * 3, w * 0.09);
	}
	pop();
}

function connect3(x, y, w, a) {
	let type = int(random(2));
	push();
	translate(x, y);
	rotate(a);
	if (type == 0) {
		line(-w / 2, -w / 4, w / 2, -w / 4);
		line(w / 4, w / 2, w / 4, w / 4);
		line(w / 4, w / 4, w / 2, w / 4);
		line(-w / 4, w / 2, -w / 4, w / 4);
		line(-w / 2, w / 4, -w / 4, w / 4);
		line(-w / 2, 0, -w / 4, 0);
		line(0, w / 4, -w / 4, 0);
		line(0, w / 4, 0, w / 2);
		line(w / 2, 0, w / 8, 0);
		line(-w / 8, -w / 4, w / 8, 0);
	} else if (type == 1) {
		line(-w / 2, -w / 4, -w / 4, 0);
		line(w / 2, 0, -w / 4, 0);
		line(-w / 2, -0, -w / 8 * 3, 0);
		line(-w / 4, w / 8, -w / 8 * 3, 0);
		line(-w / 4, w / 8, -w / 4, w / 2);
		line(-w / 2, w / 4, -w / 8 * 3, w / 4);
		line(-w / 4, w / 8 * 3, -w / 8 * 3, w / 4);
		line(0, w / 2, 0, w / 4);
		line(0, w / 4, w / 4, w / 4);
		line(w / 4, w / 2, w / 4, w / 4);
		line(-w / 8, 0, 0, -w / 8);
		line(w / 4, -w / 8, 0, -w / 8);
		line(w / 2, -w / 4, w / 4, -w / 4);
		line(w / 8, -w / 8, w / 4, -w / 4);
		line(w / 2, w / 4, w / 8 * 3, w / 4);
		line(w / 8, 0, w / 8 * 3, w / 4);
		noStroke();
		fill(clr);
		circle(w / 4, -w / 8, w * 0.09);
	}
	pop();
}

function connect4(x, y, w) {
	let type = int(random(2));
	push();
	translate(x, y);
	if (type == 0) {
		square(0, 0, w * 0.75, w * 0.02);
		for (let i = 0; i < 2; i++) {
			line(0, -w / 2, 0, -w / 8 * 3);
			line(0, w / 2, 0, w / 8 * 3);
			line(w / 4, -w / 2, w / 4, -w / 8 * 3);
			line(w / 4, w / 2, w / 4, w / 8 * 3);
			line(-w / 4, -w / 2, -w / 4, -w / 8 * 3);
			line(-w / 4, w / 2, -w / 4, w / 8 * 3);
			rotate(PI / 2);
		}
	} else if (type == 1) {
		beginShape();
		vertex(-w / 2, w / 4);
		vertex(-w / 8 * 3, w / 4);
		vertex(-w / 4, w / 8 * 3);
		vertex(-w / 4, w / 2);
		endShape();

		beginShape();
		vertex(-w / 2, 0);
		vertex(-w / 8 * 3, 0);
		vertex(0, w / 8 * 3);
		vertex(0, w / 2);
		endShape();

		beginShape();
		vertex(0, -w / 2);
		vertex(0, w / 8);
		vertex(w / 4, w / 8 * 3);
		vertex(w / 4, w / 2);
		endShape();

		line(-w / 2, -w / 4, -w / 4, -w / 2);
		line(-w / 2, 0, -w / 8, 0);
		line(w / 4, -w / 2, w / 4, 0);
		line(w / 2, -w / 4, w / 4, -w / 4);
		line(w / 2, 0, w / 4, -w / 4);
		line(w / 8 * 3, -w / 8, w / 8 * 3, w / 8);
		line(w / 2, w / 4, w / 8 * 3, w / 8);
		noStroke();
		fill(clr);
		circle(-w / 8, 0, w * 0.09);
		circle(w / 4, 0, w * 0.09);
	}
	pop();
}

